          "sceneId": "circle_invitation",
          "type": "dialogue",
          "speaker": "mizuha",
          "text": "「片づけまで手伝っていただいて、ありがとうございます」",
          "speakerLabel": "みず",
          "time": "",
          "interaction": null,
          "attachments": [],
          "reactions": [],
          "readout": [],
          "emphasis": false,
